import{_ as o,c as t,o as r,j as e,ag as s,a as i}from"./chunks/framework.DZ_cNctr.js";const n="/docs/screenshots/drop-landing.webp",d="/docs/screenshots/drop-viewer.webp",l="/docs/screenshots/open-local-files-tab.png",y=JSON.parse('{"title":"Local Files","description":"Open images, plates and slides straight from your disk. One file opens in every browser. A folder opens in Chrome and Edge. Nothing is uploaded.","frontmatter":{"title":"Local Files","description":"Open images, plates and slides straight from your disk. One file opens in every browser. A folder opens in Chrome and Edge. Nothing is uploaded."},"headers":[],"relativePath":"guides/local-files.md","filePath":"guides/local-files.md"}'),h={name:"guides/local-files.md"};function p(c,a,g,f,m,u){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"local-files",tabindex:"-1"},[i("Local Files "),e("a",{class:"header-anchor",href:"#local-files","aria-label":'Permalink to "Local Files"'},"​")],-1),e("p",null,"Open images, plates and slides from your own disk. Nothing is uploaded.",-1),e("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0",overflow:"hidden",margin:"1.5rem 0"}},[e("iframe",{src:"https://www.youtube.com/embed/p9veMmibuWA?rel=0&modestbranding=1&vq=hd720&mute=1",title:"Open Your Microscopy Data in 10 Seconds",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%",border:"0"},allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""})],-1),s('<p>Reading from disk is the fastest and most private way to work, but it is not the only one. <a href="https://www.find-nuclei.com/blog/local-vs-remote-ome-zarr" target="_blank" rel="noreferrer">Your OME-ZARR Storage Setup Is Slowing You Down</a> compares this with streaming from a server, and is worth reading before a lab or facility commits to one setup.</p><h2 id="which-browsers-can-do-this" tabindex="-1">Which Browsers Can Do This <a class="header-anchor" href="#which-browsers-can-do-this" aria-label="Permalink to &quot;Which Browsers Can Do This&quot;">​</a></h2><p>It depends on whether your data is one file or a folder.</p><table tabindex="0"><thead><tr><th>What you open</th><th>Chrome, Edge</th><th>Firefox, Safari, iPhone, iPad</th></tr></thead><tbody><tr><td>One file: a Zeiss <code>.czi</code>, an OME-TIFF, a slide (<code>.svs</code>, <code>.ndpi</code>, <code>.scn</code>, Philips <code>.tiff</code>, <code>.qptiff</code>), or a zipped OME-Zarr (<code>.ozx</code>, <code>.zip</code>)</td><td>Yes</td><td>Yes</td></tr><tr><td>A folder: an OME-Zarr dataset, an Opera Phenix or Yokogawa plate, a plate saved as one CZI per field, an MRXS or DICOM slide</td><td>Yes</td><td>No</td></tr><tr><td>A zip of one of those folders</td><td>Yes</td><td>Yes</td></tr><tr><td>A measurement table (CSV or Parquet)</td><td>Yes</td><td>No</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Folders need Chrome or Edge</p><p>Dropping a folder and picking one both work in Chrome and Edge only. Firefox and Safari cannot read a folder from a web page, and neither can any browser on an iPhone or iPad.</p><p>Zip the folder and open the zip instead. See <a href="#zip-without-compression">Zip Without Compression</a>. Or open it by address, see <a href="./remote-urls.html">Remote URLs</a>.</p></div><p>To share a folder from your own machine as an address, use the free <a href="./data-server.html">Data Server</a>.</p><h2 id="open-a-file" tabindex="-1">Open a File <a class="header-anchor" href="#open-a-file" aria-label="Permalink to &quot;Open a File&quot;">​</a></h2><p>Drop the file on the viewer. Or click <strong>Open Image</strong>, go to the <strong>Local Files</strong> tab and click <strong>Choose File</strong>.</p><div style="display:flex;flex-wrap:wrap;gap:1rem;margin:1rem 0;"><figure style="flex:1 1 260px;margin:0;"><img width="900" height="342" src="'+n+'" alt="A file dragged over the start screen: a dashed box lists what you can drop, a data folder, a zipped dataset, or a CZI, slide or OME-TIFF file" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;"><figcaption style="font-size:0.85rem;color:var(--vp-c-text-2);text-align:center;">On the start screen</figcaption></figure><figure style="flex:1 1 260px;margin:0;"><img width="900" height="368" src="'+d+'" alt="A file dragged over an open slide: the same box, with the line Asks before replacing the image you have open" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;"><figcaption style="font-size:0.85rem;color:var(--vp-c-text-2);text-align:center;">On an open image: it asks before replacing it</figcaption></figure></div><p>What opens as one file:</p><ul><li><strong>Images:</strong> a Zeiss <code>.czi</code> or an OME-TIFF.</li><li><strong>Slides:</strong> <code>.svs</code>, <code>.ndpi</code>, <code>.scn</code>, Philips <code>.tiff</code> and <code>.qptiff</code>.</li><li><strong>Zips:</strong> a zipped OME-Zarr (<code>.ozx</code> or <code>.zip</code>), a zipped Opera Phenix or Yokogawa plate, and a zip without compression of a CZI plate, an MRXS slide or a DICOM slide.</li></ul><p>Each format has its own guide: see <a href="./supported-formats.html">Supported Formats</a>. To make a zipped OME-Zarr, see <a href="./ome-zarr.html#a-dataset-in-a-single-file">A Dataset in a Single File</a>.</p><h2 id="open-a-folder" tabindex="-1">Open a Folder <a class="header-anchor" href="#open-a-folder" aria-label="Permalink to &quot;Open a Folder&quot;">​</a></h2><p>In Chrome or Edge, drop the folder on the viewer. Or click <strong>Open Image</strong>, go to the <strong>Local Files</strong> tab and click <strong>Choose Data Folder</strong>.</p><img width="1600" height="968" src="'+l+'" alt="The Local Files tab of the Open Image window, with the Choose Data Folder and Choose File buttons" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><p>What opens as a folder:</p><ul><li><strong>An OME-Zarr dataset.</strong></li><li><strong>A plate:</strong> the measurement folder of an Opera Phenix or Yokogawa plate, or a folder of one CZI per field.</li><li><strong>A slide:</strong> an MRXS slide (the <code>.mrxs</code> file with its folder) or a folder of DICOM files.</li></ul><p><strong>Dropping on an open image.</strong> No need to close what you have first. The viewer asks before it replaces your image, and <strong>Cancel</strong> leaves your view as it was.</p><h3 id="if-the-folder-holds-datasets" tabindex="-1">If the Folder Holds Datasets <a class="header-anchor" href="#if-the-folder-holds-datasets" aria-label="Permalink to &quot;If the Folder Holds Datasets&quot;">​</a></h3><p>Open a folder that holds several images, and the viewer lists them. Pick one and it opens.</p><p>This works for every format: OME-Zarr datasets, CZI files and slides. One folder can mix them, say Aperio <code>.svs</code> and Hamamatsu <code>.ndpi</code> side by side.</p><p>The names in the list come from the data, not from the folder names. A dataset called <code>plate-3</code> is found just as well as one called <code>sample.ome.zarr</code>.</p><p>Nothing is uploaded to make the list. The viewer reads it on your computer.</p><h2 id="zip-without-compression" tabindex="-1">Zip Without Compression <a class="header-anchor" href="#zip-without-compression" aria-label="Permalink to &quot;Zip Without Compression&quot;">​</a></h2><p>Plates and slides saved as several large files need a zip made without compression. The viewer then reads only the parts it needs, from your disk or a web address. These files are already compressed, so a compressed zip saves little space, and the viewer asks you to make the zip again. Opera Phenix and Yokogawa plates are the exception: they open from either kind of zip.</p><p><strong>On a Mac or Linux.</strong> Run this next to the folder:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> slide.zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> slide</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*.DS_Store&#39;</span></span></code></pre></div><p><code>-0</code> turns compression off, and <code>-x</code> leaves out the hidden files a Mac adds.</p><p><strong>On Windows.</strong> In <a href="https://www.7-zip.org/" target="_blank" rel="noreferrer">7-Zip</a>, right-click the folder and choose <strong>7-Zip</strong>, then <strong>Add to archive</strong>. Set <strong>Archive format</strong> to <strong>zip</strong> and <strong>Compression level</strong> to <strong>Store</strong>.</p><p>The built-in <strong>Compress</strong> in Finder and <strong>Compressed (zipped) folder</strong> in Explorer both compress. They suit an OME-Zarr folder, not these files.</p><p><strong>To check a zip.</strong> Run <code>unzip -v slide.zip</code>. Every file should say <code>Stored</code> in the <strong>Method</strong> column.</p><h2 id="recent-images" tabindex="-1">Recent Images <a class="header-anchor" href="#recent-images" aria-label="Permalink to &quot;Recent Images&quot;">​</a></h2><p>What you open appears in <strong>Recently Opened</strong> on the landing page. Click it to reopen. Your annotations, channel settings and contrast are as you left them.</p><p>The viewer remembers where your data is, not a copy of it. So reopening asks you to confirm:</p><table tabindex="0"><thead><tr><th></th><th>Chrome, Edge</th><th>Firefox, Safari</th></tr></thead><tbody><tr><td>Reopen a file or folder from Recent</td><td>One permission click</td><td>Pick the file again</td></tr></tbody></table><p>Chrome and Edge can keep a lasting pointer to your file, so you only allow access. Firefox and Safari cannot, so they ask for the file again. Either way you land back on the same image, with everything as you left it.</p><div class="tip custom-block"><p class="custom-block-title">Why the viewer does not keep a copy</p><p>A browser can store a whole file in its own storage, and then Recent would work everywhere with no prompt. That makes a second copy of your data: a 10 MB file grew browser storage by 10.5 MB in our test. For a plate or a slide, that is gigabytes, written somewhere you did not choose. Pointing at the file again is the smaller price.</p></div><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshots use <code>CMU-1.svs</code> from the OpenSlide test data, CC0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>Your data stays entirely on your machine. Find Nuclei Viewer processes everything locally in the browser. No files are uploaded to any server.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./remote-urls.html">Remote URLs</a>: the third route, and the one to use when the data lives on a server</li><li><a href="./data-server.html">Data Server</a>: serve a folder from your own machine over HTTP, so local data opens anywhere</li><li><a href="./ome-zarr.html">OME-Zarr</a>: a whole dataset in one zipped file</li><li><a href="./supported-formats.html">Supported Formats</a>: every format, and how it opens</li></ul>',43)])])}const b=o(h,[["render",p]]);export{y as __pageData,b as default};
